const req = $('Webhook').first().json.body ?? {};
const phone = String(req.phone ?? '').trim();
const res = $json ?? {};

// Cratio answers {"error":"NO RECORDS FOUND"} on a miss and
// {"success":[{"totalrows":N,"data":[...]}]} on a hit.
const rows = Number(res?.success?.[0]?.totalrows ?? 0);
const found = !res.error && (rows > 0 || JSON.stringify(res).includes(phone));

// A token, not the phone number. If this echoed the value back, a not-found
// reply would still contain it and the check would read every lost lead as
// delivered — silent failure in the check whose whole job is catching it.
return [{ json: { result: found ? 'LEAD_FOUND' : 'LEAD_MISSING', checked: phone, rows } }];
